// Shared static markup keeps the flag identical in React and Steam Store views.
export type HungarianSource = "steam" | "curator" | null;

export function getHungarianBadgeHtml(source: HungarianSource = "steam"): string {
  return source === "curator"
    ? HUNGARIAN_BADGE_HTML.replace('aria-label="Hivatalos magyar nyelvi támogatás"', 'aria-label="Magyar nyelv a Magyar Felirat kurátor szerint"')
      .replace('title="Hivatalos magyar nyelvi támogatás a Steam adatai szerint"', 'title="Magyar nyelv – forrás: Magyar Felirat Steam-kurátor"')
    : HUNGARIAN_BADGE_HTML;
}

// The 2:1 tricolour remains crisp at the small sizes used on game covers.
export const HUNGARIAN_BADGE_HTML = '<span role="img" aria-label="Hivatalos magyar nyelvi támogatás" title="Hivatalos magyar nyelvi támogatás a Steam adatai szerint" style="box-sizing:border-box;width:34px;height:24px;display:inline-flex;flex-shrink:0;align-items:center;justify-content:center;border-radius:5px;background:rgba(6,9,18,.92);box-shadow:0 1px 5px rgba(0,0,0,.85),inset 0 0 0 1px rgba(255,255,255,.12);pointer-events:none"><svg xmlns="http://www.w3.org/2000/svg" width="28" height="14" viewBox="0 0 30 15" aria-hidden="true" style="display:block;border-radius:2px;overflow:hidden"><path fill="#ce2939" d="M0 0h30v5H0z"/><path fill="#fff" d="M0 5h30v5H0z"/><path fill="#477050" d="M0 10h30v5H0z"/><rect x=".5" y=".5" width="29" height="14" rx="1.5" fill="none" stroke="#fff" stroke-opacity=".18"/></svg></span>';
